replace_once("    OPEN_LOOP_KEY,\n    RHYTHM_KEY,\n", "    OPEN_LOOP_KEY,\n    TODAY_INTENT_KEY,\n    RHYTHM_KEY,\n", 'managed intent key')

validation_anchor = """    if(key===OPEN_LOOP_KEY){\n      return Array.isArray(value) && value.every(x=>\n        isRecord(x) && typeof x.id==='string' && typeof x.text==='string'\n      );\n    }\n\n    if(key===RHYTHM_KEY){\n"""
validation_add = """    if(key===OPEN_LOOP_KEY){\n      return Array.isArray(value) && value.every(x=>\n        isRecord(x) && typeof x.id==='string' && typeof x.text==='string'\n      );\n    }\n\n    if(key===TODAY_INTENT_KEY){\n      const allowedKinds=new Set(['loop','time_block','routine','bundle_item','deferred_bundle_item']);\n      return isRecord(value) && Object.entries(value).every(([date,items])=>\n        looksLikeDate(date) && Array.isArray(items) && items.every(item=>\n          isRecord(item) && typeof item.id==='string' && allowedKinds.has(item.kind)\n        )\n      );\n    }\n\n    if(key===RHYTHM_KEY){\n"""
