replace_once("  let openLoops = loadOpenLoops();\n  let rhythmDefs = loadRhythmDefs();\n", "  let openLoops = loadOpenLoops();\n  let todayIntent = loadTodayIntent();\n  let rhythmDefs = loadRhythmDefs();\n", 'intent runtime state')

# Intent model and helpers: explicit human choice layered over existing source-of-truth records.
open_loop_anchor = """  function loadOpenLoops(){\n    const value=readStore(OPEN_LOOP_KEY,[]);\n    return Array.isArray(value) ? value : [];\n  }\n  function saveOpenLoops(){ localStorage.setItem(OPEN_LOOP_KEY, JSON.stringify(openLoops)); }\n\n  function activeOpenLoops(){\n"""
open_loop_add = """  function loadOpenLoops(){\n    const value=readStore(OPEN_LOOP_KEY,[]);\n    return Array.isArray(value) ? value : [];\n  }\n  function saveOpenLoops(){ localStorage.setItem(OPEN_LOOP_KEY, JSON.stringify(openLoops)); }\n\n  function loadTodayIntent(){\n    const value=readStore(TODAY_INTENT_KEY,{});\n    return isRecord(value) ? value : {};\n  }\n  function saveTodayIntent(){ localStorage.setItem(TODAY_INTENT_KEY,JSON.stringify(todayIntent)); }\n\n  function intentSpecKey(spec){\n    if(!spec) return '';\n    if(spec.kind==='loop' || spec.kind==='time_block') return `${spec.kind}:${spec.refId || ''}`;\n    if(spec.kind==='routine') return `routine:${spec.defId || ''}:${spec.originDate || ''}`;\n    if(spec.kind==='bundle_item') return `bundle_item:${spec.defId || ''}:${spec.itemId || ''}:${spec.originDate || ''}`;\n    if(spec.kind==='deferred_bundle_item') return `deferred_bundle_item:${spec.defId || ''}:${spec.itemId || ''}:${spec.originDate || ''}`;\n    return `${spec.kind || 'intent'}:${spec.refId || spec.id || ''}`;\n  }\n\n  function intentRecordsForDate(dateStr){\n    const items=todayIntent[dateStr];\n    return Array.isArray(items) ? items : [];\n  }\n\n  function intentSelected(dateStr,spec){\n    const key=intentSpecKey(spec);\n    return intentRecordsForDate(dateStr).some(item=>intentSpecKey(item)===key);\n  }\n\n  function addIntent(dateStr,spec,{carriedFrom=null}={}){\n    if(!looksLikeDate(dateStr) || !spec || !spec.kind) return null;\n    const current=intentRecordsForDate(dateStr).slice();\n    const key=intentSpecKey(spec);\n    const existing=current.find(item=>intentSpecKey(item)===key);\n    if(existing){\n      existing.laterUntil=null;\n      existing.carriedFrom=carriedFrom || existing.carriedFrom || null;\n      todayIntent[dateStr]=current;\n      saveTodayIntent();\n      return existing;\n    }\n    const item={\n      id:'intent_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,6),\n      ...spec,\n      titleSnapshot:spec.titleSnapshot || spec.title || '',\n      addedAt:new Date().toISOString(),\n      laterUntil:null,\n      carriedFrom\n    };\n    todayIntent[dateStr]=[...current,item];\n    saveTodayIntent();\n    return item;\n  }\n\n  function removeIntent(dateStr,id,{refresh=true}={}){\n    const current=intentRecordsForDate(dateStr);\n    const next=current.filter(item=>item.id!==id);\n    if(next.length) todayIntent[dateStr]=next;\n    else delete todayIntent[dateStr];\n    saveTodayIntent();\n    if(refresh) refreshViews('intent');\n  }\n\n  function toggleIntent(dateStr,spec){\n    const current=intentRecordsForDate(dateStr);\n    const key=intentSpecKey(spec);\n    const existing=current.find(item=>intentSpecKey(item)===key);\n    if(existing) removeIntent(dateStr,existing.id,{refresh:false});\n    else addIntent(dateStr,spec);\n    refreshViews('intent');\n  }\n\n  function snoozeIntent(dateStr,id,minutes=90){\n    const item=intentRecordsForDate(dateStr).find(x=>x.id===id);\n    if(!item) return;\n    item.laterUntil=new Date(Date.now()+minutes*60000).toISOString();\n    saveTodayIntent();\n    refreshViews('intent');\n  }\n\n  function intentIsSnoozed(item){\n    if(!item?.laterUntil) return false;\n    return new Date(item.laterUntil).getTime()>Date.now();\n  }\n\n  function todayIntentButton(spec,{dateStr=iso(new Date()),className='todayIntentBtn'}={}){\n    const btn=document.createElement('button');\n    btn.type='button';\n    btn.className=className+(intentSelected(dateStr,spec)?' selected':'');\n    btn.textContent=intentSelected(dateStr,spec)?'In Today':'Today';\n    btn.dataset.intentKind=spec.kind;\n    const ref=spec.refId || spec.itemId || spec.defId || '';\n    if(ref) btn.dataset.intentRef=ref;\n    btn.addEventListener('click',()=>toggleIntent(dateStr,spec));\n    return btn;\n  }\n\n  function activeOpenLoops(){\n"""
replace_once(open_loop_anchor, open_loop_add, 'intent helpers')

# Resolve intent back to the underlying canonical data. Resolved/completed records disappear automatically.
resolve_anchor = """  function loopCreatedLabel(item){\n"""
resolve_block = """  function resolveIntentRecord(record,dateStr){\n    if(!record) return null;\n\n    if(record.kind==='loop'){\n      const loop=openLoops.find(x=>x.id===record.refId && x.status!=='done');\n      if(!loop) return null;\n      return {\n        title:loop.text,kind:'loop',effort:'medium',\n        actionLabel:'Done',\n        action:()=>completeLoop(loop.id)\n      };\n    }\n\n    if(record.kind==='time_block'){\n      const block=timeBlocks.find(x=>x.id===record.refId);\n      if(!block || block.date!==dateStr || ['completed','canceled'].includes(timeBlockStatus(block))) return null;\n      const status=timeBlockStatus(block);\n      return {\n        title:block.title,kind:'commitment',effort:'fixed',started:status==='active',\n        actionLabel:status==='active'?'End now':'View',\n        action:()=>status==='active'?endTimeBlockNow(block.id):openTimeBlockModal(block.id)\n      };\n    }\n\n    if(record.kind==='routine'){\n      const def=rhythmDefs.find(x=>x.id===record.defId);\n      if(!def) return null;\n      const stateDate=record.originDate || dateStr;\n      const state=rhythmOccurrenceState(def.id,stateDate);\n      if(state.status==='done' || state.status==='skipped') return null;\n      return {\n        title:def.name,kind:'routine',effort:'medium',\n        actionLabel:'Done',\n        action:()=>markRoutineDone(def,stateDate,record.source || 'scheduled')\n      };\n    }\n\n    if(record.kind==='bundle_item' || record.kind==='deferred_bundle_item'){\n      const def=rhythmDefs.find(x=>x.id===record.defId);\n      const child=def ? routineItems(def).find(x=>x.id===record.itemId) : null;\n      if(!def || !child) return null;\n      const stateDate=record.originDate || dateStr;\n      const state=bundleItemState(def.id,stateDate,child.id);\n      if(state.status==='done') return null;\n      return {\n        title:child.text,kind:'routine',effort:'medium',started:state.status==='in_progress' || state.deferredProgress==='in_progress',\n        actionLabel:'Done',\n        action:()=>{\n          setBundleItemState(def,stateDate,child.id,'done',{\n            completedAt:new Date().toISOString(),\n            completedOn:dateStr,\n            deferTo:null,\n            deferredProgress:null\n          });\n          refreshViews('rhythm');\n        }\n      };\n    }\n\n    return null;\n  }\n\n  function intentSpecFromRecord(record){\n    return {\n      kind:record.kind,refId:record.refId || null,defId:record.defId || null,itemId:record.itemId || null,\n      originDate:record.originDate || null,source:record.source || null,titleSnapshot:record.titleSnapshot || ''\n    };\n  }\n\n  function completeIntentRecord(dateStr,record){\n    const resolved=resolveIntentRecord(record,dateStr);\n    removeIntent(dateStr,record.id,{refresh:false});\n    if(resolved?.action) resolved.action();\n    else refreshViews('intent');\n  }\n\n  function loopCreatedLabel(item){\n"""
replace_once(resolve_anchor, resolve_block, 'intent resolver')

