timeblock_add = """      const edit=document.createElement('button');\n      edit.className='timeBlockBtn';\n      edit.textContent=(status==='completed' || status==='active') ? 'Edit actual' : 'Edit';\n      edit.addEventListener('click',()=>openTimeBlockModal(item.id));\n      actions.appendChild(edit);\n\n      if(isToday && (status==='planned' || status==='active')){\n        actions.appendChild(todayIntentButton({\n          kind:'time_block',refId:item.id,titleSnapshot:item.title\n        },{className:'timeBlockBtn todayIntentBtn'}));\n      }\n\n      if(status==='planned'){\n"""
