routine_actions_add = """        const skip=document.createElement('button');\n        skip.className='rhythmBtn skip';\n        skip.textContent='Not this week';\n        skip.addEventListener('click',()=>skipRoutine(item.def,dateStr,item.source));\n\n        if(dateStr===iso(new Date())){\n          actions.appendChild(todayIntentButton({\n            kind:'routine',defId:item.def.id,originDate:dateStr,source:item.source,titleSnapshot:item.def.name\n          },{className:'rhythmBtn todayIntentBtn'}));\n        }\n        actions.append(done,defer,skip);\n        row.appendChild(actions);\n      }\n\n      box.appendChild(row);\n"""
