# Shortlist/carryover renderer and explicit-intent adaptive candidates.
adaptive_anchor = """  function adaptiveDaypartBonus(daypart,minute){\n"""
adaptive_helpers = """  function shortlistMeta(record,resolved){\n    if(intentIsSnoozed(record)){\n      return `Later until ${new Date(record.laterUntil).toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'})}`;\n    }\n    if(record.carriedFrom) return `Kept from ${parseISO(record.carriedFrom).toLocaleDateString(undefined,{weekday:'short'})}`;\n    return resolved.kind==='commitment' ? 'Chosen for today · scheduled' : 'Chosen for today';\n  }\n\n  function renderShortlistAction(container,label,handler,className=''){\n    const btn=document.createElement('button');\n    btn.type='button';\n    btn.className=`shortlistAction ${className}`.trim();\n    btn.textContent=label;\n    btn.addEventListener('click',handler);\n    container.appendChild(btn);\n  }\n\n  function carryoverRecordsFor(dateStr){\n    const previous=iso(addDays(parseISO(dateStr),-1));\n    return intentRecordsForDate(previous)\n      .filter(record=>record.kind!=='time_block')\n      .map(record=>({record,resolved:resolveIntentRecord(record,previous),previous}))\n      .filter(entry=>entry.resolved);\n  }\n\n  function renderTodayShortlist(){\n    const wrap=$('todayShortlistWrap');\n    if(!wrap) return [];\n    const dateStr=iso(new Date());\n    let current=intentRecordsForDate(dateStr).slice();\n    const valid=[];\n    let changed=false;\n\n    current.forEach(record=>{\n      const resolved=resolveIntentRecord(record,dateStr);\n      if(resolved) valid.push({record,resolved});\n      else changed=true;\n    });\n    if(changed){\n      if(valid.length) todayIntent[dateStr]=valid.map(entry=>entry.record);\n      else delete todayIntent[dateStr];\n      saveTodayIntent();\n      current=valid.map(entry=>entry.record);\n    }\n\n    const carry=carryoverRecordsFor(dateStr);\n    wrap.style.display=(valid.length || carry.length) ? 'block' : 'none';\n    $('todayShortlistCount').textContent=valid.length ? `${valid.length} chosen` : '';\n\n    const list=$('todayShortlist');\n    list.innerHTML='';\n    valid.slice(0,3).forEach(({record,resolved})=>{\n      const row=document.createElement('div');\n      row.className='todayShortlistItem';\n      row.dataset.intentId=record.id;\n\n      const copy=document.createElement('div');\n      const title=document.createElement('div');\n      title.className='todayShortlistTitle';\n      title.textContent=resolved.title;\n      const meta=document.createElement('div');\n      meta.className='todayShortlistMeta';\n      meta.textContent=shortlistMeta(record,resolved);\n      copy.append(title,meta);\n\n      const actions=document.createElement('div');\n      actions.className='todayShortlistActions';\n      if(resolved.actionLabel==='Done' || resolved.actionLabel==='End now'){\n        renderShortlistAction(actions,resolved.actionLabel,()=>completeIntentRecord(dateStr,record),'done');\n      }else if(resolved.action){\n        renderShortlistAction(actions,resolved.actionLabel || 'Open',resolved.action,'done');\n      }\n      renderShortlistAction(actions,'Later',()=>snoozeIntent(dateStr,record.id,90),'later');\n      renderShortlistAction(actions,'Remove',()=>removeIntent(dateStr,record.id));\n      row.append(copy,actions);\n      list.appendChild(row);\n    });\n    $('todayShortlistMore').textContent=valid.length>3 ? `+ ${valid.length-3} more chosen for today` : '';\n\n    const carryPanel=$('carryoverPanel');\n    const carryList=$('carryoverList');\n    carryList.innerHTML='';\n    carryPanel.classList.toggle('show',Boolean(carry.length));\n    $('carryoverTitle').textContent=carry.length\n      ? `${carry.length} thing${carry.length===1?'':'s'} carried over from yesterday`\n      : '';\n\n    carry.forEach(({record,resolved,previous})=>{\n      const row=document.createElement('div');\n      row.className='carryoverItem';\n      row.dataset.carryoverIntentId=record.id;\n      const copy=document.createElement('div');\n      const title=document.createElement('div');\n      title.className='todayShortlistTitle';\n      title.textContent=resolved.title;\n      const meta=document.createElement('div');\n      meta.className='todayShortlistMeta';\n      meta.textContent='Unfinished from yesterday · choose what happens next.';\n      copy.append(title,meta);\n\n      const actions=document.createElement('div');\n      actions.className='carryoverActions';\n      renderShortlistAction(actions,'Keep today',()=>{\n        removeIntent(previous,record.id,{refresh:false});\n        addIntent(dateStr,intentSpecFromRecord(record),{carriedFrom:previous});\n        refreshViews('intent');\n      },'done');\n      renderShortlistAction(actions,record.kind==='loop'?'Return to loops':'Leave yesterday',()=>removeIntent(previous,record.id));\n      if(resolved.actionLabel==='Done'){\n        renderShortlistAction(actions,'Done',()=>completeIntentRecord(previous,record),'done');\n      }\n      row.append(copy,actions);\n      carryList.appendChild(row);\n    });\n\n    return valid.map(entry=>entry.record);\n  }\n\n  function buildIntentCandidates(dateStr){\n    return intentRecordsForDate(dateStr)\n      .filter(record=>!intentIsSnoozed(record))\n      .map(record=>{\n        const resolved=resolveIntentRecord(record,dateStr);\n        if(!resolved) return null;\n        return {\n          id:`intent:${record.id}`,\n          entityKey:intentSpecKey(record),\n          kind:resolved.kind,\n          title:resolved.title,\n          reason:record.carriedFrom\n            ? 'Carried from yesterday · you kept this for today.'\n            : 'You chose this for today.',\n          baseScore:64,\n          intent:true,\n          started:Boolean(resolved.started),\n          effort:resolved.effort || 'medium',\n          actionLabel:resolved.actionLabel || 'Done',\n          action:resolved.action,\n          secondaryLabel:'Later',\n          secondaryAction:()=>snoozeIntent(dateStr,record.id,90)\n        };\n      })\n      .filter(Boolean);\n  }\n\n  function adaptiveDaypartBonus(daypart,minute){\n"""
replace_once(adaptive_anchor, adaptive_helpers, 'adaptive intent helpers')

# Intent is explicit but still below hard commitments. Rank deduplicates a chosen item against its inferred copy.
replace_once("""    if(candidate.started) score+=18;\n    if(candidate.hard) score+=20;\n\n    if(context.lowEnergy && !candidate.started){\n""", """    if(candidate.started) score+=18;\n    if(candidate.hard) score+=20;\n    if(candidate.intent) score+=30;\n\n    if(context.lowEnergy && !candidate.started){\n""", 'intent ranking boost')

rank_anchor = """  function rankAdaptiveCandidates(candidates,context={}){\n    return candidates\n      .map((candidate,index)=>({\n        ...candidate,\n        adaptiveScore:adaptiveScoreCandidate(candidate,context),\n        adaptiveOrder:index\n      }))\n      .filter(candidate=>candidate.adaptiveScore>=0)\n      .sort((a,b)=>b.adaptiveScore-a.adaptiveScore || a.adaptiveOrder-b.adaptiveOrder);\n  }\n"""
